const formData = $input.first().json;

const typeOrg = formData['Type d'organisation'] || formData['Type d organisation'] || '';
const nomEntreprise = formData['Nom de l'entreprise/organisation'] || formData['Nom de l entreprise/organisation'] || '';
const secteur = formData['Secteur d'activité'] || formData['Secteur d activité'] || '';
const emailContact = formData['Email de contact'] || '';
const telephone = formData['Téléphone'] || formData['Telephone'] || '';
const typeSite = formData['Type de site web souhaité'] || formData['Type de site web souhaite'] || '';
const objectif = formData['Objectif principal du site'] || '';
const publicCible = formData['Public cible'] || '';
const fonctionnalites = formData['Fonctionnalités souhaitées'] || formData['Fonctionnalites souhaitees'] || '';
const charteGraphique = formData['Avez-vous une charte graphique existante?'] || '';
const couleurs = formData['Couleurs préférées'] || formData['Couleurs preferees'] || 'Non spécifié';
const styleVisuel = formData['Style visuel souhaité'] || formData['Style visuel souhaite'] || '';
const sitesRef = formData['Sites web de référence'] || formData['Sites web de reference'] || 'Aucune référence fournie';
const contenu = formData['Contenu disponible'] || '';
const nbPages = formData['Nombre de pages estimé'] || formData['Nombre de pages estime'] || '';
const langues = formData['Langues du site'] || '';
const seo = formData['Besoins SEO'] || '';
const integrations = formData['Intégrations nécessaires'] || formData['Integrations necessaires'] || 'Aucune intégration spécifique';
const budget = formData['Budget approximatif'] || '';
const delai = formData['Délai souhaité'] || formData['Delai souhaite'] || '';
const maintenance = formData['Maintenance et hébergement'] || formData['Maintenance et hebergement'] || '';
const infosComp = formData['Informations complémentaires'] || formData['Informations complementaires'] || 'Aucune information complémentaire';

const prompt = `# Cahier des Charges - Création de Site Web

## 1. INFORMATIONS CLIENT
- **Type d'organisation** : ${typeOrg}
- **Nom** : ${nomEntreprise}
- **Secteur d'activité** : ${secteur}
- **Contact** : ${emailContact}${telephone ? ` - ${telephone}` : ''}

## 2. TYPE DE PROJET
- **Type de site web** : ${typeSite}
- **Objectif principal** : ${objectif}
- **Public cible** : ${publicCible}

## 3. FONCTIONNALITÉS REQUISES
${fonctionnalites}

## 4. DESIGN ET IDENTITÉ VISUELLE
- **Charte graphique existante** : ${charteGraphique}
- **Couleurs préférées** : ${couleurs}
- **Style visuel** : ${styleVisuel}
- **Sites de référence** :
${sitesRef}

## 5. CONTENU
- **Statut du contenu** : ${contenu}
- **Nombre de pages** : ${nbPages}
- **Langues** : ${langues}

## 6. OPTIMISATION ET INTÉGRATIONS
- **Besoins SEO** : ${seo}
- **Intégrations nécessaires** :
${integrations}

## 7. CONTRAINTES PROJET
- **Budget** : ${budget}
- **Délai** : ${delai}
- **Maintenance** : ${maintenance}

## 8. INFORMATIONS COMPLÉMENTAIRES
${infosComp}

---

## PROMPT POUR DÉVELOPPEUR/DESIGNER

Créer un site web ${typeSite.toLowerCase()} pour ${nomEntreprise}, une organisation de type "${typeOrg}" dans le secteur ${secteur}.

**Objectif :** ${objectif}

**Public cible :** ${publicCible}

**Style visuel :** ${styleVisuel} avec des tons ${couleurs}.

**Fonctionnalités clés à développer :**
${fonctionnalites}

**Structure :** Le site comprendra ${nbPages} en ${langues}.

**SEO :** Mettre en place ${seo.toLowerCase()}.

**Contraintes :**
- Budget : ${budget}
- Délai : ${delai}
- Charte graphique : ${charteGraphique}
- Contenu : ${contenu}

${integrations !== 'Aucune intégration spécifique' ? `**Intégrations requises :**
${integrations}

` : ''}${sitesRef !== 'Aucune référence fournie' ? `**Inspirations :**
${sitesRef}

` : ''}${infosComp !== 'Aucune information complémentaire' ? `**Notes supplémentaires :**
${infosComp}` : ''}`;

return {
  json: {
    prompt: prompt,
    rawData: formData,
    generatedAt: new Date().toISOString(),
    clientName: nomEntreprise,
    clientEmail: emailContact,
    projectType: typeSite,
    budget: budget,
    deadline: delai
  }
};
